// ---------------------------------------------------------------- library
const LIB = store.get("lib", { q: "", category: [], moment: [], rating: ["clean", "mild"], ranked: false, offset: 0 });
async function Library() {
  view.innerHTML = `
    <div class="row"><div><h1>Asset library</h1><p class="sub">Every sound, meme, green screen and graphic in the Editing Pack, tagged for the auto-editor.</p></div></div>
    <div class="filters card">
      <div class="row">
        <input id="q" type="search" placeholder="Search: creeper, sad violin, bruh, diamond…" style="flex:1;min-width:240px" value="${esc(LIB.q)}">
        <select id="momentSel"><option value="">+ moment…</option>${Object.entries(TAX.moments).map(([k, v]) => `<option value="${k}" title="${esc(v)}">${k}</option>`).join("")}</select>
        <label class="chip ${LIB.ranked ? "on" : ""}" id="ranked" title="Use the planner's scoring (needs a moment or search)">★ Planner ranking</label>
        <select id="rootSel"><option value="">All libraries</option><option value="Editing Pack" ${LIB.root === "Editing Pack" ? "selected" : ""}>Editing Pack</option><option value="Stock Library" ${LIB.root === "Stock Library" ? "selected" : ""}>My Stock Library</option></select>
        <button class="btn primary" id="addFootage">＋ Add footage</button>
      </div>
      <div class="chips" id="cats">${Object.keys(TAX.categories).filter((c) => c !== "reference").map((c) =>
        `<span class="chip ${LIB.category.includes(c) ? "on" : ""}" data-c="${c}" title="${esc(TAX.categories[c])}">${c.replace("_", " ")}</span>`).join("")}</div>
      <div class="row">
        <div class="chips" id="moments">${LIB.moment.map((m) => `<span class="chip on" data-m="${m}">${m} ✕</span>`).join("")}</div>
        <span class="spacer"></span>
        <div class="chips" id="ratings">${Object.keys(TAX.content_rating).map((r) =>
          `<span class="chip ${LIB.rating.includes(r) ? "on" : ""}" data-r="${r}">${r}</span>`).join("")}</div>
      </div>
    </div>
    <div class="row muted" id="count"></div>
    <div class="grid" id="grid"></div>
    <div class="pager" id="pager"></div>`;
  let t;
  $("#q").addEventListener("input", (e) => { clearTimeout(t); t = setTimeout(() => { LIB.q = e.target.value; LIB.offset = 0; load(); }, 250); });
  $("#momentSel").addEventListener("change", (e) => { if (e.target.value && !LIB.moment.includes(e.target.value)) LIB.moment.push(e.target.value); e.target.value = ""; LIB.offset = 0; Library(); });
  $("#moments").addEventListener("click", (e) => { const m = e.target.dataset.m; if (m) { LIB.moment = LIB.moment.filter((x) => x !== m); LIB.offset = 0; Library(); } });
  $("#cats").addEventListener("click", (e) => { const c = e.target.dataset.c; if (!c) return; toggle(LIB.category, c); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
  $("#ratings").addEventListener("click", (e) => { const r = e.target.dataset.r; if (!r) return; toggle(LIB.rating, r); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
  $("#ranked").addEventListener("click", (e) => { LIB.ranked = !LIB.ranked; e.target.classList.toggle("on"); load(); });
  $("#rootSel").addEventListener("change", (e) => { LIB.root = e.target.value; LIB.offset = 0; load(); });
  $("#addFootage").onclick = addFootage;
  load();

  async function load() {
    store.set("lib", LIB);
    const p = new URLSearchParams({ q: LIB.q, limit: 60, offset: LIB.offset, ranked: LIB.ranked, root: LIB.root || "" });
    LIB.category.forEach((c) => p.append("category", c));
    LIB.moment.forEach((m) => p.append("moment", m));
    LIB.rating.forEach((r) => p.append("rating", r));
    const res = await api("/api/assets?" + p);
    let items = res.items;
    if (LIB.ranked) items = items.filter((a) => !LIB.rating.length || LIB.rating.includes(a.content_rating));
    $("#count").textContent = `${LIB.ranked ? items.length + " best matches" : res.total + " assets"}`;
    $("#grid").innerHTML = items.map(assetCard).join("") || `<div class="empty">No assets match. Loosen the filters.</div>`;
    $$("#grid .asset").forEach((el, i) => {
      el.addEventListener("click", (e) => { if (e.target.closest(".play")) return; openAsset(items[i].id); $$(".asset.sel").forEach((x) => x.classList.remove("sel")); el.classList.add("sel"); });
      const pb = $(".play", el); if (pb) pb.addEventListener("click", () => playAsset(items[i], pb));
    });
    const pages = Math.ceil(res.total / 60), cur = LIB.offset / 60;
    $("#pager").innerHTML = LIB.ranked || pages <= 1 ? "" :
      `<button class="btn small" ${cur === 0 ? "disabled" : ""} id="prev">← Prev</button><span>Page ${cur + 1} / ${pages}</span><button class="btn small" ${cur + 1 >= pages ? "disabled" : ""} id="next">Next →</button>`;
    $("#prev")?.addEventListener("click", () => { LIB.offset -= 60; load(); scrollTo(0, 0); });
    $("#next")?.addEventListener("click", () => { LIB.offset += 60; load(); scrollTo(0, 0); });
  }
}
async function addFootage() {
  const st = await api("/api/library/status");
  const m = $("#modal");
  m.innerHTML = `<div class="modal-box"><div class="modal-head"><b>Add to your Stock Library</b><span class="spacer"></span><button class="btn small" id="mclose">✕</button></div>
    <div class="modal-body" style="padding:16px;display:grid;gap:12px">
      <div class="muted">${st.library_assets} assets in your library · ${st.untagged} waiting to be tagged</div>
      <label class="field">Folder<select id="lfolder">${st.folders.map((f) => `<option>${esc(f)}</option>`).join("")}</select></label>
      <label class="field">Files (video, audio, images)<input id="lfiles" type="file" multiple accept="video/*,audio/*,image/*"></label>
      <div class="row"><button class="btn primary" id="lup">Upload &amp; scan</button><span id="lmsg" class="muted"></span></div>
      <hr style="border-color:var(--line);width:100%">
      <div><b>Tagging</b> <span class="muted">(Claude looks at each clip and files it: subject, mood, moments, where it fits)</span></div>
      <textarea rows="3" id="lprompt">${esc(st.tag_prompt)}</textarea>
      <div class="row">${st.claude ? `<button class="btn gold" id="ltag">Tag new assets with Claude</button>` : `<button class="btn" id="lcopy">Copy prompt for Claude Code</button>`}</div>
    </div></div>`;
  m.hidden = false;
  $("#mclose").onclick = () => (m.hidden = true);
  $("#lup").onclick = async () => {
    const files = $("#lfiles").files;
    if (!files.length) return toast("Pick some files first", true);
    const fd = new FormData(); fd.append("folder", $("#lfolder").value); [...files].forEach((f) => fd.append("files", f));
    $("#lmsg").textContent = `Uploading ${files.length} file(s)…`;
    const r = await fetch("/api/library/upload", { method: "POST", body: fd });
    if (!r.ok) return toast("Upload failed", true);
    const j = await r.json(); $("#lmsg").textContent = `Saved ${j.saved.length}. Scanning (see Jobs)…`;
  };
  $("#lcopy")?.addEventListener("click", () => { navigator.clipboard.writeText($("#lprompt").value); toast("Prompt copied"); });
  $("#ltag")?.addEventListener("click", async () => { try { await api("/api/library/tag", { method: "POST" }); toast("Tagging started (see Jobs)"); m.hidden = true; } catch (e) { toast(e.message, true); } });
}

function toggle(arr, v) { const i = arr.indexOf(v); i >= 0 ? arr.splice(i, 1) : arr.push(v); }
function ratingBadge(r) { return r ? `<span class="badge r-${r}">${r}</span>` : ""; }
function assetCard(a) {
  const audio = a.kind === "audio";
  const thumb = a.thumb ? `style="background-image:url('/media/catalog/${a.thumb}')"` : "";
  const playable = a.kind === "audio" || (a.kind === "video" && a.has_audio);
  return `<div class="asset" title="${esc(a.id)}">
    <div class="thumb ${audio ? "audio" : ""}" ${thumb}>
      ${audio ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}
      ${playable ? `<span class="play" title="Play">▶</span>` : ""}
      ${a.duration_s ? `<span class="dur">${a.duration_s.toFixed(1)}s</span>` : ""}
    </div>
    <div class="meta">
      <div class="title">${esc(a.title)}</div>
      <div class="desc">${esc(a.description || "")}</div>
      <div class="badges"><span class="badge">${a.category}</span>${ratingBadge(a.content_rating)}
        ${a.copyright_risk === "high" ? `<span class="badge k-risk-high">© high</span>` : ""}
        ${a.key_mode && a.key_mode !== "none" ? `<span class="badge">${a.key_mode}</span>` : ""}
        ${a.score != null ? `<span class="badge" style="color:var(--gold)">★ ${a.score}</span>` : ""}</div>
    </div></div>`;
}
function playAsset(a, btn) {
  const url = packUrl(a.path, a.root);
  if (!player.paused && player.dataset.id === a.id) { player.pause(); btn.textContent = "▶"; return; }
  $$(".play").forEach((b) => (b.textContent = "▶"));
  player.src = url; player.dataset.id = a.id;
  player.currentTime = 0; player.play().catch(() => toast("Can't play this format in the browser", true));
  btn.textContent = "❚❚";
  player.onended = () => (btn.textContent = "▶");
}
function closeDrawer() { const d = $("#drawer"); d.hidden = true; d.innerHTML = ""; }
async function openAsset(id) {
  const a = await api("/api/assets/" + encodeURIComponent(id));
  const d = $("#drawer");
  const url = packUrl(a.path, a.root);
  const media = a.kind === "video" ? `<video src="${url}" controls preload="metadata"></video>`
    : a.kind === "audio" ? `<audio src="${url}" controls style="width:100%"></audio>`
    : a.kind === "image" ? `<img class="preview" src="${url}">`
    : a.thumb ? `<img class="preview" src="/media/catalog/${a.thumb}">` : "";
  const opt = (list, cur) => list.map((v) => `<option ${v === cur ? "selected" : ""}>${v}</option>`).join("");
  d.innerHTML = `<button class="btn small close" id="dclose">✕</button>
    <h3>${esc(a.title)}</h3>
    <div class="row" style="margin-bottom:10px"><code class="mono">${esc(a.id)}</code><button class="btn small" id="copyId">Copy ID</button></div>
    ${media}
    <p>${esc(a.description || "")}</p>
    <div class="chips">${a.moments.map((m) => `<span class="chip on">${m}</span>`).join("")}${a.roles.map((r) => `<span class="chip">${r}</span>`).join("")}</div>
    <dl class="kv">
      <dt>Category</dt><dd>${a.category} · ${esc(a.subfolder)}</dd>
      <dt>Rating</dt><dd>${ratingBadge(a.content_rating)} <span class="badge k-risk-${a.copyright_risk}">© ${a.copyright_risk || "?"}</span></dd>
      ${a.quote ? `<dt>Quote</dt><dd>“${esc(a.quote)}”</dd>` : ""}
      <dt>Energy / mood</dt><dd>${a.energy ?? "–"} / ${esc(a.mood || "–")}</dd>
      <dt>Duration</dt><dd>${a.duration_s ? a.duration_s.toFixed(2) + "s" : "–"} ${a.peak_s != null ? `· hit @ ${a.peak_s}s` : ""} ${a.use_in != null ? `· use ${a.use_in}–${a.use_out}s` : ""}</dd>
      ${a.width ? `<dt>Size</dt><dd>${a.width}×${a.height}${a.fps ? " @ " + a.fps : ""}</dd>` : ""}
      ${a.key_mode && a.key_mode !== "none" ? `<dt>Key</dt><dd>${a.key_mode} ${a.key_color || ""}</dd>` : ""}
      <dt>Placement</dt><dd>${a.placement || "–"} · ${a.frequency || "–"}</dd>
      <dt>Tags</dt><dd>${a.tags.map(esc).join(", ")}</dd>
      ${a.notes ? `<dt>Notes</dt><dd>${esc(a.notes)}</dd>` : ""}
      <dt>Used in</dt><dd>${a.used_in.map((u) => `${esc(u.project)} (${u.n})`).join(", ") || "never"}</dd>
      <dt>File</dt><dd class="mono">${esc(a.path)}</dd>
    </dl>
    <h2>Correct tags</h2>
    <div style="display:grid;gap:8px">
      <div class="row">
        <label class="field">Rating<select id="eRating">${opt(Object.keys(TAX.content_rating), a.content_rating)}</select></label>
        <label class="field">Copyright<select id="eRisk">${opt(Object.keys(TAX.copyright_risk), a.copyright_risk)}</select></label>
        <label class="field">Energy<input id="eEnergy" type="number" min="1" max="5" value="${a.energy ?? 3}" style="width:70px"></label>
      </div>
      <label class="field">Moments (comma separated)<input id="eMoments" type="text" value="${esc(a.moments.join(", "))}"></label>
      <label class="field">Description<input id="eDesc" type="text" value="${esc(a.description || "")}"></label>
      <label class="field">Notes<input id="eNotes" type="text" value="${esc(a.notes || "")}"></label>
      <div><button class="btn primary" id="eSave">Save correction</button> <span class="faint" style="font-size:12px">stored in catalog/overrides.json</span></div>
    </div>`;
  d.hidden = false;
  $("#dclose").onclick = closeDrawer;
  $("#copyId").onclick = () => { navigator.clipboard.writeText(a.id); toast("Copied " + a.id); };
  $("#eSave").onclick = async () => {
    const moments = $("#eMoments").value.split(",").map((s) => s.trim()).filter(Boolean);
    const bad = moments.filter((m) => !TAX.moments[m]);
    if (bad.length) return toast("Unknown moments: " + bad.join(", "), true);
    try {
      await api("/api/assets/" + encodeURIComponent(a.id), { method: "PATCH", body: { fields: {
        content_rating: $("#eRating").value, copyright_risk: $("#eRisk").value, energy: +$("#eEnergy").value,
        moments, description: $("#eDesc").value, notes: $("#eNotes").value || null } } });
      toast("Saved"); openAsset(a.id); refreshSide();
    } catch (e) { toast(e.message, true); }
  };
}

// ---------------------------------------------------------------- projects
async function Projects() {
  const all = await api("/api/projects");
  const ps = all.filter((p) => p.kind !== "short");
  view.innerHTML = `<div class="row"><div><h1>Episodes</h1><p class="sub">Drop in footage → one click → a finished video plus 9:16 shorts.</p></div>
    <span class="spacer"></span><a class="btn primary" href="#/new">＋ New episode</a></div>
    ${ps.length ? `<div class="proj-grid">${ps.map(projCard).join("")}</div>` : `<div class="empty">No episodes yet. <a href="#/new">Create one from an OBS recording.</a></div>`}`;
}
