def _read_favorites() -> list[str]:
    try:
        return list(json.loads(FAVORITES.read_text(encoding="utf-8")).get("ids") or [])
    except (OSError, ValueError, AttributeError):
        return []


def _favorite_ids() -> set[str]:
    return {resolve(i) for i in _read_favorites()}


def set_favorite(asset_id: str, on: bool) -> dict:
    """Star / unstar an asset: updates favorites.json (survives rebuilds) and the DB row (no rebuild)."""
    asset_id = resolve(asset_id)
    con = connect()
    con.execute("BEGIN IMMEDIATE")   # serialise with merge_catalog.py and other writers
    try:
        if not con.execute("SELECT 1 FROM assets WHERE id = ?", (asset_id,)).fetchone():
            raise KeyError(asset_id)
        # drop the id and any old alias of it, then re-add the canonical id
        ids = [i for i in _read_favorites() if resolve(i) != asset_id]
        if on:
            ids.append(asset_id)
        tmp = FAVORITES.with_name(f"favorites.json.{os.getpid()}.tmp")
        tmp.write_text(json.dumps({"ids": sorted(set(ids))}, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
        os.replace(tmp, FAVORITES)
        con.execute("UPDATE assets SET favorite = ? WHERE id = ?", (int(on), asset_id))
        con.commit()
    except BaseException:
        con.rollback()
        raise
    finally:
        con.close()
    return get(asset_id)


def favorites() -> list[dict]:
    con = connect()
    rows = con.execute("SELECT * FROM assets WHERE favorite = 1 ORDER BY category, title").fetchall()
    return [as_dict(r) for r in rows]

